#include <stdio.h>

int main() {
    int a[5] = {5, 2, 9, 1, 7};
    int t;
    for (int j = 0; j < 4; j++) {
        if (a[j] > a[j + 1]) {
            t = a[j];
            a[j] = a[j + 1];
            a[j + 1] = t;
        }
    }
    for (int i = 0; i < 5; i++)
        printf("%d ", a[i]);
    return 0;
}

class Util {
    static int sum(int a, int b) {
        return a + b;
    }
    static int sum(int a, int b, int c) {
        return a + b + c;
    }
    static int sum(int[] a) {
        int s = 0;
        for (int x : a)
            s += x;
        return s;
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.print(Util.sum(1, 2));
        System.out.print(",");
        System.out.print(Util.sum(1, 2, 3));
        System.out.print(",");
        System.out.print(Util.sum(new int[] {1, 2, 3, 4}));
    }
}

